function actualizarReloj(){const ahora=new Date();const horas=ahora.getHours().toString().padStart(2,'0');const minutos=ahora.getMinutes().toString().padStart(2,'0');const segundos=ahora.getSeconds().toString().padStart(2,'0');document.getElementById('horas').textContent=horas;document.getElementById('minutos').textContent=minutos;document.getElementById('segundos').textContent=segundos;const opciones={weekday:'long',year:'numeric',month:'long',day:'numeric'};const fecha=ahora.toLocaleDateString('es-ES',opciones);document.getElementById('fecha').textContent=fecha}
actualizarReloj();setInterval(actualizarReloj,1000)